-- complaint_redress: Redress action for a complaint (refund, fee reversal, goodwill); money moves via payments/ledger
CREATE TABLE complaint_redress (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  updated_at                   timestamptz NOT NULL DEFAULT now(),
  updated_by                   varchar(64),
  row_version                  integer NOT NULL DEFAULT 1,
  complaint_id                 uuid NOT NULL REFERENCES complaint(id),
  redress_type                 varchar(40) NOT NULL CHECK (redress_type IN ('REFUND', 'FEE_REVERSAL', 'INTEREST_ADJUSTMENT', 'GOODWILL_PAYMENT', 'APOLOGY', 'PROCESS_CHANGE')),
  amount                       numeric(28,8),
  currency                     char(3),
  target_account_id            uuid,
  ledger_id                    uuid,
  funding_account_id           uuid,
  journal_entry_id             uuid,
  approval_request_id          uuid,
  status                       varchar(40) NOT NULL DEFAULT 'PROPOSED' CHECK (status IN ('PROPOSED', 'APPROVED', 'PAID', 'REJECTED', 'FAILED')),
  description                  varchar(500),
  approved_by                  varchar(64),
  approved_at                  timestamptz,
  approval_comment             varchar(500),
  rejection_reason             varchar(255),
  failure_reason               varchar(500),
  paid_at                      timestamptz,
  custom_field_1               varchar(500),
  custom_field_2               varchar(500),
  custom_field_3               varchar(500),
  custom_field_4               varchar(500),
  custom_field_5               varchar(500)
);
COMMENT ON TABLE complaint_redress IS 'Redress action for a complaint (refund, fee reversal, goodwill); money moves via payments/ledger';
COMMENT ON COLUMN complaint_redress.id IS 'Unique id (UUIDv7, time-ordered)';
COMMENT ON COLUMN complaint_redress.tenant_id IS 'Owning tenant; enforced by row-level security';
