-- interaction: One contact with a customer on any channel; together these form the customer timeline
CREATE TABLE interaction (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  updated_at                   timestamptz NOT NULL DEFAULT now(),
  updated_by                   varchar(64),
  row_version                  integer NOT NULL DEFAULT 1,
  customer_id                  uuid NOT NULL,
  interaction_type             varchar(40) NOT NULL CHECK (interaction_type IN ('CALL_INBOUND', 'CALL_OUTBOUND', 'CHAT', 'EMAIL_INBOUND', 'EMAIL_OUTBOUND', 'SMS', 'PUSH', 'BRANCH_VISIT', 'MEETING', 'LETTER', 'SOCIAL', 'IN_APP_MESSAGE', 'VIDEO_CALL')),
  direction                    varchar(40) NOT NULL CHECK (direction IN ('INBOUND', 'OUTBOUND')),
  channel                      varchar(40) NOT NULL CHECK (channel IN ('MOBILE_APP', 'WEB', 'PHONE', 'EMAIL', 'CHAT', 'WHATSAPP', 'BRANCH', 'AGENT', 'SOCIAL_MEDIA', 'LETTER', 'USSD', 'API')),
  service_case_id              uuid REFERENCES service_case(id),
  complaint_id                 uuid REFERENCES complaint(id),
  staff_user_id                uuid,
  subject                      varchar(255),
  summary                      text,
  transcript_document_id       uuid,
  started_at                   timestamptz NOT NULL,
  ended_at                     timestamptz,
  duration_seconds             integer,
  sentiment                    varchar(40) CHECK (sentiment IN ('VERY_NEGATIVE', 'NEGATIVE', 'NEUTRAL', 'POSITIVE', 'VERY_POSITIVE')),
  intent                       varchar(64),
  external_ref                 varchar(128),
  custom_field_1               varchar(500),
  custom_field_2               varchar(500),
  custom_field_3               varchar(500),
  custom_field_4               varchar(500),
  custom_field_5               varchar(500)
);
COMMENT ON TABLE interaction IS 'One contact with a customer on any channel; together these form the customer timeline';
COMMENT ON COLUMN interaction.id IS 'Unique id (UUIDv7, time-ordered)';
COMMENT ON COLUMN interaction.tenant_id IS 'Owning tenant; enforced by row-level security';
COMMENT ON COLUMN interaction.created_at IS 'Creation time';
