COMMENT ON COLUMN interaction.updated_at IS 'Last update time';
COMMENT ON COLUMN interaction.updated_by IS 'Principal that last updated the row';
COMMENT ON COLUMN interaction.row_version IS 'Optimistic lock version; send as If-Match';
COMMENT ON COLUMN interaction.customer_id IS 'Customer';
COMMENT ON COLUMN interaction.interaction_type IS 'Interaction type';
COMMENT ON COLUMN interaction.direction IS 'Direction';
COMMENT ON COLUMN interaction.channel IS 'Channel';
COMMENT ON COLUMN interaction.service_case_id IS 'Linked case';
COMMENT ON COLUMN interaction.complaint_id IS 'Linked complaint';
COMMENT ON COLUMN interaction.staff_user_id IS 'Staff member';
COMMENT ON COLUMN interaction.subject IS 'Subject';
COMMENT ON COLUMN interaction.summary IS 'Summary or transcript excerpt [PII]';
COMMENT ON COLUMN interaction.transcript_document_id IS 'Full transcript / recording reference';
COMMENT ON COLUMN interaction.started_at IS 'Start';
COMMENT ON COLUMN interaction.ended_at IS 'End';
COMMENT ON COLUMN interaction.duration_seconds IS 'Duration';
COMMENT ON COLUMN interaction.sentiment IS 'Detected sentiment';
COMMENT ON COLUMN interaction.intent IS 'Detected intent';
COMMENT ON COLUMN interaction.external_ref IS 'Contact-centre or email system id';
