-- canned_response: Approved reply template for cases and complaints, with placeholders
CREATE TABLE canned_response (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  updated_at                   timestamptz NOT NULL DEFAULT now(),
  updated_by                   varchar(64),
  row_version                  integer NOT NULL DEFAULT 1,
  code                         varchar(64) NOT NULL,
  title                        varchar(160) NOT NULL,
  body                         text NOT NULL,
  language                     varchar(10) NOT NULL DEFAULT 'en',
  case_type                    varchar(40) CHECK (case_type IN ('SERVICE_REQUEST', 'INQUIRY', 'CARD_ISSUE', 'PAYMENT_ISSUE', 'ACCOUNT_MAINTENANCE', 'DOCUMENT_REQUEST', 'FRAUD_REPORT', 'TECHNICAL_ISSUE', 'LOAN_SERVICING', 'KYC_UPDATE', 'CLOSURE_REQUEST', 'OTHER')),
  complaint_category           varchar(40) CHECK (complaint_category IN ('FEES_AND_CHARGES', 'SERVICE_QUALITY', 'FRAUD_AND_SCAMS', 'PAYMENTS', 'CARDS', 'LENDING', 'ACCOUNT_OPENING', 'ACCOUNT_CLOSURE', 'DATA_PRIVACY', 'DISCRIMINATION', 'MIS_SELLING', 'COLLECTIONS_CONDUCT', 'DIGITAL_CHANNELS', 'OTHER')),
  channel                      varchar(40) CHECK (channel IN ('MOBILE_APP', 'WEB', 'PHONE', 'EMAIL', 'CHAT', 'WHATSAPP', 'BRANCH', 'AGENT', 'SOCIAL_MEDIA', 'LETTER', 'USSD', 'API')),
  is_active                    boolean NOT NULL DEFAULT true,
  custom_field_1               varchar(500),
  custom_field_2               varchar(500),
  custom_field_3               varchar(500),
  custom_field_4               varchar(500),
  custom_field_5               varchar(500),
  CONSTRAINT uq_canned_response_code UNIQUE (tenant_id, code)
);
COMMENT ON TABLE canned_response IS 'Approved reply template for cases and complaints, with placeholders';
COMMENT ON COLUMN canned_response.id IS 'Unique id (UUIDv7, time-ordered)';
COMMENT ON COLUMN canned_response.tenant_id IS 'Owning tenant; enforced by row-level security';
COMMENT ON COLUMN canned_response.created_at IS 'Creation time';
COMMENT ON COLUMN canned_response.created_by IS 'Principal that created the row';
COMMENT ON COLUMN canned_response.updated_at IS 'Last update time';
COMMENT ON COLUMN canned_response.updated_by IS 'Principal that last updated the row';
COMMENT ON COLUMN canned_response.row_version IS 'Optimistic lock version; send as If-Match';
COMMENT ON COLUMN canned_response.code IS 'Template code';
COMMENT ON COLUMN canned_response.title IS 'Title';
COMMENT ON COLUMN canned_response.body IS 'Template body with placeholders';
COMMENT ON COLUMN canned_response.language IS 'Language';
COMMENT ON COLUMN canned_response.case_type IS 'Case type';
COMMENT ON COLUMN canned_response.complaint_category IS 'Complaint category';
COMMENT ON COLUMN canned_response.channel IS 'Channel';
COMMENT ON COLUMN canned_response.is_active IS 'Active';
COMMENT ON COLUMN canned_response.custom_field_1 IS 'Tenant-defined custom field 1; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN canned_response.custom_field_2 IS 'Tenant-defined custom field 2; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN canned_response.custom_field_3 IS 'Tenant-defined custom field 3; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN canned_response.custom_field_4 IS 'Tenant-defined custom field 4; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN canned_response.custom_field_5 IS 'Tenant-defined custom field 5; label, type and validation configured in custom_field_definition';
CREATE INDEX ix_canned_response_tenant ON canned_response (tenant_id, created_at);
ALTER TABLE canned_response ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON canned_response USING (tenant_id = current_setting('app.tenant_id')::uuid);
CREATE TRIGGER trg_canned_response_touch BEFORE UPDATE ON canned_response FOR EACH ROW EXECUTE FUNCTION touch_row();

-- copilot_session: One AI copilot invocation by a staff member, with inputs, output, sources and feedback (audit trail)
CREATE TABLE copilot_session (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  staff_user_id                uuid NOT NULL,
  task                         varchar(40) NOT NULL CHECK (task IN ('SUMMARISE_CUSTOMER', 'SUMMARISE_CASE', 'DRAFT_REPLY', 'CLASSIFY_CASE', 'SUGGEST_NEXT_ACTION', 'ANSWER_QUESTION', 'DRAFT_COMPLAINT_RESPONSE', 'TRANSLATE')),
  customer_id                  uuid,
  service_case_id              uuid REFERENCES service_case(id),
  complaint_id                 uuid REFERENCES complaint(id),
  prompt                       text,
  language                     varchar(10),
  prompt_hash                  varchar(64),
  context_refs                 jsonb NOT NULL,
  output                       text NOT NULL,
  output_hash                  varchar(64) NOT NULL,
  citations                    jsonb,
  model                        varchar(64) NOT NULL,
  model_gateway_request_id     varchar(128),
  input_tokens                 integer,
  output_tokens                integer,
  latency_ms                   integer,
  pii_redacted                 boolean NOT NULL DEFAULT true,
  guardrail_flags              jsonb,
  custom_field_1               varchar(500),
  custom_field_2               varchar(500),
  custom_field_3               varchar(500),
  custom_field_4               varchar(500),
  custom_field_5               varchar(500)
);
COMMENT ON TABLE copilot_session IS 'One AI copilot invocation by a staff member, with inputs, output, sources and feedback (audit trail)';
COMMENT ON COLUMN copilot_session.id IS 'Unique id (UUIDv7, time-ordered)';
COMMENT ON COLUMN copilot_session.tenant_id IS 'Owning tenant; enforced by row-level security';
COMMENT ON COLUMN copilot_session.created_at IS 'Creation time';
COMMENT ON COLUMN copilot_session.created_by IS 'Principal that created the row';
COMMENT ON COLUMN copilot_session.staff_user_id IS 'Staff member who invoked the copilot';
COMMENT ON COLUMN copilot_session.task IS 'Task';
COMMENT ON COLUMN copilot_session.customer_id IS 'Customer in context';
COMMENT ON COLUMN copilot_session.service_case_id IS 'Case in context';
COMMENT ON COLUMN copilot_session.complaint_id IS 'Complaint in context';
COMMENT ON COLUMN copilot_session.prompt IS 'Staff prompt or question [PII]';
COMMENT ON COLUMN copilot_session.language IS 'Target language (TRANSLATE) or reply language';
COMMENT ON COLUMN copilot_session.prompt_hash IS 'SHA-256 of the prompt as sent to the model (audit)';
COMMENT ON COLUMN copilot_session.context_refs IS 'Records and articles retrieved as grounding';
COMMENT ON COLUMN copilot_session.output IS 'Generated summary, draft or answer [PII]';
COMMENT ON COLUMN copilot_session.output_hash IS 'SHA-256 of the output (audit)';
COMMENT ON COLUMN copilot_session.citations IS 'Sources cited in the output';
COMMENT ON COLUMN copilot_session.model IS 'Model id used';
COMMENT ON COLUMN copilot_session.model_gateway_request_id IS 'Request id at the model gateway';
COMMENT ON COLUMN copilot_session.input_tokens IS 'Input tokens';
COMMENT ON COLUMN copilot_session.output_tokens IS 'Output tokens';
COMMENT ON COLUMN copilot_session.latency_ms IS 'Latency';
COMMENT ON COLUMN copilot_session.pii_redacted IS 'PII redacted before sending to the model';
COMMENT ON COLUMN copilot_session.guardrail_flags IS 'Guardrail triggers, if any';
COMMENT ON COLUMN copilot_session.custom_field_1 IS 'Tenant-defined custom field 1; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN copilot_session.custom_field_2 IS 'Tenant-defined custom field 2; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN copilot_session.custom_field_3 IS 'Tenant-defined custom field 3; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN copilot_session.custom_field_4 IS 'Tenant-defined custom field 4; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN copilot_session.custom_field_5 IS 'Tenant-defined custom field 5; label, type and validation configured in custom_field_definition';
CREATE INDEX ix_copilot_session_tenant ON copilot_session (tenant_id, created_at);
CREATE INDEX ix_copilot_session_staff_user_id ON copilot_session (staff_user_id);
CREATE INDEX ix_copilot_session_customer_id ON copilot_session (customer_id);
CREATE INDEX ix_copilot_session_service_case_id ON copilot_session (service_case_id);
CREATE INDEX ix_copilot_session_complaint_id ON copilot_session (complaint_id);
ALTER TABLE copilot_session ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON copilot_session USING (tenant_id = current_setting('app.tenant_id')::uuid);
CREATE TRIGGER trg_copilot_session_append_only BEFORE UPDATE OR DELETE ON copilot_session FOR EACH ROW EXECUTE FUNCTION forbid_mutation();

-- copilot_feedback: Staff feedback on a copilot output (accepted, edited, rejected)
CREATE TABLE copilot_feedback (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  copilot_session_id           uuid NOT NULL REFERENCES copilot_session(id),
