-- case_comment: Comment on a case, internal or visible to the customer
CREATE TABLE case_comment (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  updated_at                   timestamptz NOT NULL DEFAULT now(),
  updated_by                   varchar(64),
  row_version                  integer NOT NULL DEFAULT 1,
  service_case_id              uuid NOT NULL REFERENCES service_case(id),
  visibility                   varchar(40) NOT NULL DEFAULT 'INTERNAL' CHECK (visibility IN ('INTERNAL', 'CUSTOMER')),
  author_type                  varchar(40) NOT NULL DEFAULT 'STAFF' CHECK (author_type IN ('STAFF', 'CUSTOMER', 'SYSTEM', 'COPILOT')),
  author_id                    uuid,
  author_name                  varchar(64),
  body                         text NOT NULL,
  attachments                  jsonb,
  copilot_session_id           uuid REFERENCES copilot_session(id),
  custom_field_1               varchar(500),
  custom_field_2               varchar(500),
  custom_field_3               varchar(500),
  custom_field_4               varchar(500),
  custom_field_5               varchar(500)
);
COMMENT ON TABLE case_comment IS 'Comment on a case, internal or visible to the customer';
COMMENT ON COLUMN case_comment.id IS 'Unique id (UUIDv7, time-ordered)';
COMMENT ON COLUMN case_comment.tenant_id IS 'Owning tenant; enforced by row-level security';
COMMENT ON COLUMN case_comment.created_at IS 'Creation time';
COMMENT ON COLUMN case_comment.created_by IS 'Principal that created the row';
COMMENT ON COLUMN case_comment.updated_at IS 'Last update time';
COMMENT ON COLUMN case_comment.updated_by IS 'Principal that last updated the row';
COMMENT ON COLUMN case_comment.row_version IS 'Optimistic lock version; send as If-Match';
COMMENT ON COLUMN case_comment.service_case_id IS 'Case';
COMMENT ON COLUMN case_comment.visibility IS 'Who can see it';
COMMENT ON COLUMN case_comment.author_type IS 'STAFF, CUSTOMER, SYSTEM, COPILOT';
COMMENT ON COLUMN case_comment.author_id IS 'Staff user or customer id';
COMMENT ON COLUMN case_comment.author_name IS 'Principal that wrote the comment';
COMMENT ON COLUMN case_comment.body IS 'Comment text [PII]';
COMMENT ON COLUMN case_comment.attachments IS 'Document ids';
COMMENT ON COLUMN case_comment.copilot_session_id IS 'Copilot draft this comment came from';
COMMENT ON COLUMN case_comment.custom_field_1 IS 'Tenant-defined custom field 1; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN case_comment.custom_field_2 IS 'Tenant-defined custom field 2; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN case_comment.custom_field_3 IS 'Tenant-defined custom field 3; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN case_comment.custom_field_4 IS 'Tenant-defined custom field 4; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN case_comment.custom_field_5 IS 'Tenant-defined custom field 5; label, type and validation configured in custom_field_definition';
CREATE INDEX ix_case_comment_tenant ON case_comment (tenant_id, created_at);
CREATE INDEX ix_case_comment_service_case_id ON case_comment (service_case_id);
CREATE INDEX ix_case_comment_copilot_session_id ON case_comment (copilot_session_id);
ALTER TABLE case_comment ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON case_comment USING (tenant_id = current_setting('app.tenant_id')::uuid);
CREATE TRIGGER trg_case_comment_touch BEFORE UPDATE ON case_comment FOR EACH ROW EXECUTE FUNCTION touch_row();

-- Transactional outbox: events are written here in the same transaction as the
-- state change and relayed to Kafka by the outbox relay (Debezium); relayed rows stay for the replay window.
CREATE TABLE outbox (
  id              uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id       uuid NOT NULL,
  aggregate_type  varchar(64) NOT NULL,
  aggregate_id    uuid NOT NULL,
  event_type      varchar(128) NOT NULL,
  payload         jsonb NOT NULL,
  headers         jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at      timestamptz NOT NULL DEFAULT now(),
  published_at    timestamptz
);
COMMENT ON COLUMN outbox.published_at IS 'When the relay published the event (NULL = pending). Relayed rows are kept for the replay window (meridian.events.retention.window) and then purged (MR-GAME-DAY)';
CREATE INDEX ix_outbox_pending ON outbox (created_at, id) WHERE published_at IS NULL;
CREATE INDEX ix_outbox_published ON outbox (published_at) WHERE published_at IS NOT NULL;
CREATE INDEX ix_outbox_created ON outbox (created_at);

-- Idempotency keys for POST requests (24h retention).
CREATE TABLE idempotency_key (
  tenant_id       uuid NOT NULL,
  key             varchar(128) NOT NULL,
  request_hash    varchar(64) NOT NULL,
  response_status integer,
  response_body   jsonb,
  created_at      timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, key)
);

-- Runtime access for the non-superuser application role (RLS does not apply to superusers).
DO $$
BEGIN
  IF EXISTS (SELECT FROM pg_roles WHERE rolname = 'meridian_app') THEN
    GRANT USAGE ON SCHEMA crm TO meridian_app;
    GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA crm TO meridian_app;
    ALTER DEFAULT PRIVILEGES IN SCHEMA crm GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO meridian_app;
  END IF;
END $$;
